import { esc, options, empty } from '../ui.js';
export const articles=[{id:'start',title:'איך מתחילים בהדגמה?',category:'תחילת עבודה',text:'פתחו את רשימת הרשומות, חפשו ארגון לדוגמה ולחצו על שמו. תוכלו לשנות פרטים ולשמור אותם בדפדפן. לאחר השמירה השינוי יופיע ברשימה ובמרכז הפעילות.'},{id:'board',title:'עבודה עם שלבים',category:'עבודה שוטפת',text:'בלוח העבודה אפשר לשנות את שלב הרשומה דרך הרשימה הנפתחת. במחשב אפשר גם לגרור כרטיס לעמודה אחרת. השינוי מעדכן את אותם נתוני הדגמה שמוצגים בלוח הניהולי.'},{id:'reset',title:'חזרה לנקודת ההתחלה',category:'תחילת עבודה',text:'כפתור איפוס ההדגמה משחזר את הנתונים הפיקטיביים. האיפוס מתייחס לפרויקט ההדגמה הזה בלבד. כל העדכונים הקודמים שביצעתם בו יוסרו לאחר אישור.'}];
export default function knowledge({ui}) {
 const rows=articles.filter(a=>(!ui.knowledgeQuery||(a.title+a.text).includes(ui.knowledgeQuery))&&(!ui.knowledgeCategory||a.category===ui.knowledgeCategory));
 return `<div class="toolbar"><label class="field grow"><span>חיפוש מדריך</span><input id="knowledge-query" data-field="knowledgeQuery" value="${esc(ui.knowledgeQuery)}"></label><label class="field"><span>נושא</span><select data-field="knowledgeCategory" id="knowledge-category">${options(['','תחילת עבודה','עבודה שוטפת'],ui.knowledgeCategory)}</select></label></div><div class="grid">${rows.map(a=>`<article class="template-card"><span class="tag">${a.category}</span><h3 style="margin-top:20px">${a.title}</h3><p>${a.text.slice(0,75)}…</p><button class="outline" data-action="article" data-id="${a.id}">פתיחת המדריך</button></article>`).join('')}</div>${rows.length?'':empty('לא נמצאו מדריכים','נסו חיפוש אחר.')}`;
}
